-- Rifts World Book 8: Japan - its power armor and robots (printed 132-181),
-- with their M.D.C.-by-location tables and weapon systems. See
-- apps/character-creator/docs/surveys/japan.md, step 8.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-japan-vehicles.sql
--
-- TEXT LAYER, page_offset +1, but every M.D.C. table and weapon block was read
-- off a render: the stat blocks interleave in the text layer, and several pages
-- carry heavy digit-cipher damage. Four book-extract-workers, two book-reconcile
-- passes.
--
-- WHAT IS HERE (all new; no slug or name matched an existing vehicle):
--   power armor  the ArmaTech "Samurai Class" SAMAS (PA-10A), the USA-G10A1
--                Point and USA-G10A2 Hawkeye Glitter Boys, the ATPA-85
--                Power-Spy, the H-Brand Ninjabot, and Ichto's IPA-40, -45, -50,
--                -60, -62 and -70
--   robots       AT-1053 Ka-Kuma, AT-1063 Hi-Tora, IR-2015 Kani, IR-2020
--                Wrecker, IR-2040 Destroyer, IR-2050 Apocalypse, IR-2060
--                Banshee, IR-2070 Gemini, IR-4000 Tatsu, and the Apocalypse's
--                detachable aerial combat drone as its own row (the book gives
--                it its own stat block, printed 173)
--
-- NOT HERE: the Glitter Boy of printed 136-137 is the core book's, already the
-- vehicle row glitter-boy-power-armor. The Optional GB Weapon Systems box
-- (printed 142) lets any Glitter Boy swap its main gun; its entries are weapon
-- rows on the Point and Hawkeye (numbered 11 up to keep them apart from each
-- suit's own), and the underwater M-BiLAR only on the Point, as printed.
--
-- PRICES: cost is the new price of the named model; knock-off, used and
-- variant prices are in cost_note. A machine never sold stores NULL.
--
-- BOOK SLIPS, stored as printed and noted in the rows: the Gemini's "44 when
-- invisible" dodge, the IPA-62's 8 feet (2.1 m), the IPA-70's 6D6 S.D.C.
-- restrained punch. A weapon with both S.D.C. and M.D. settings is flagged
-- mega-damage, the unit of its combat settings; its damage text keeps both.

INSERT OR IGNORE INTO vehicles
  (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, cost, cost_note, description, source_book)
VALUES
  ('at-samurai-samas-pa-10a', 'ArmaTech "Samurai Class" SAMAS Power Armor (PA-10A)', 'rifts', 'power-armor', 'One', NULL, 'Running 60 mph (96 kmph) maximum, at 10% of the usual fatigue rate; unassisted leap 15 ft (4.6 m) high or across; thruster-assisted leap up to 100 ft (30.5 m) high and 200 ft (61 m) across', 'Hover, or fly at 320 mph (512 kmph) maximum, 150 mph (240 kmph) cruising; maximum altitude about 6000 ft (1828 m); jets need to cool after 10 hours above cruising speed or 20 hours at cruising speed', NULL, 'Height 8 ft (2.4 m); Width 3.5 ft (1.06 m) wings down, 11 ft (3.3 m) wings extended; Length 4 ft 6 in (1.4 m)', '340 lbs (153 kg) without the particle beam gun', 290, 1600000, '1.6 million credits new, full power, with particle beam rifle. Rarely on the black market, usually 3-4 million there. H-Brand has no copy and cannot duplicate the P-beam rifle. Fielded by the Republic of Japan: 10,000 defend Nagasaki, 22,000 more on military duty elsewhere.', 'ArmaTech''s Japanese version of the Coalition SAMAS, styled like samurai armor, with small improvements and a particle beam rifle in place of the rail gun. Belly and helmet carry searchlights, and slots on each forearm are really mini-missile launchers. It serves the Republic as patrol, recon, infantry-strike, rescue and seek-and-destroy armor. Physical strength equals P.S. 30 and the nuclear plant lasts about 20 years. Full optics; sensor bonuses apply to long-range weapons only: +2 to strike and +1 to dodge. Hand to hand is mega-damage per Power Armor Combat Training in the Rifts RPG (p.45).', 'Rifts World Book 8: Japan p.134-135'),
  ('usa-g10a1-point-glitter-boy', '"Point" Glitter Boy (USA-G10A1)', 'rifts', 'power-armor', 'One pilot', NULL, 'Running 90 mph (145 kmph) maximum; leaps 15 ft (4.6 m) high or across, +15 ft with a running start; thruster-assisted leaps 100 ft (30.5 m) high or lengthwise', 'Not capable of flight; thrusters can hold it up to 100 ft (30.5 m) off the ground for about four minutes', NULL, 'Height 7 ft 10 in (2.4 m); Width 3 ft 10 in (1.15 m); Length 3 ft 8 in (1.1 m)', '1 ton fully loaded', 480, NULL, 'No price printed. Used exclusively by the Republic of Japan military; only a handful of rebuilt or stolen GBs of any type reach criminals, rival kingdoms, mercs or adventurers. Very rare.', 'A scaled-down, reconnaissance version of the Glitter Boy built by ArmaTech, with camouflage paint (S.D.C., so it strips off under M.D. fire to expose the laser-resistant chrome). The Boom Gun is replaced by a shoulder-slung multi-barrel laser rifle and a forearm rail gun, so it needs no stabilizing pylons and is lighter and more mobile. P.S. 30, nuclear power (25 years). Hand to hand bonuses +1 initiative and +2 roll with punch or impact, no prowl penalty until the paint is stripped (-15%). Sensors: passive nightvision, infrared and ultraviolet optics, molecular analyzer, and a closed circuit camera that streams or records up to 12 hours to command. Laser weapons do half damage to it.', 'Rifts World Book 8: Japan p.137-140'),
  ('usa-g10a2-hawkeye-glitter-boy', '"Hawkeye" Glitter Boy (USA-G10A2)', 'rifts', 'power-armor', 'One pilot', NULL, 'Running 60 mph (96 kmph) maximum; cannot leap (missile and long-range weapons prevent it)', 'Not capable of flight', NULL, 'Height 10 ft 5 in (3.1 m); Width 4 ft 4 in (1.3 m); Length 4 ft (1.2 m)', '1.2 tons fully loaded', 770, NULL, 'No price printed. Used exclusively by the Republic of Japan military; a tiny handful of rebuilt or stolen GBs of any type reach criminals, rival kingdoms, mercs or adventurers. Extremely rare. Japanese GB squads field at least one, up to three where heavy air contact is expected.', 'The anti-aircraft Glitter Boy: the standard G10 body with the Boom Gun and stabilizer thrusters swapped for a back-mounted medium-range missile launcher, a shoulder mini-missile box, forearm launchers and an extra power supply, making it a mobile surface-to-air battery that also works against armor, dragons and supernatural threats. No pylon needed, so it can turn to face any direction. P.S. 30, nuclear power (25 years). Special combat bonuses +3 initiative (extended radar) and +1 roll with punch, fall or impact. Sensors add radar tracking 200 targets out to 50 miles (80 km), and a radar jammer that halves the effectiveness of all radar within 5 miles (8 km), its own included (-50% to read sensory instruments). Laser weapons do half damage to it.', 'Rifts World Book 8: Japan p.140-142'),
  ('atpa-85-power-spy', 'ATPA-85 "Power-Spy"', 'rifts', 'power-armor', 'One', NULL, 'Running adds 20 to the wearer natural Spd, at 20% of the usual fatigue rate; leaps 20 ft (6.1 m) straight up or lengthwise from a standstill', 'No built-in flight; an attachable jet pack typically flies 180 mph (288 kmph), about 4000 ft (122 m) altitude, one hour of fuel (may tap the armor power for indefinite flight)', NULL, 'Height, Width, Length: form fitting, about 6 in (0.15 m) larger than the wearer; add 2 ft (0.6 m) for a jet pack', '90 lbs (40.8 kg)', 110, 450000, '450,000 credits undamaged and fully powered. Exclusive to the Republic of Japan armed forces; a handful on the black market and with secret and criminal organizations; availability terrible even there. Ichto and H-Brand make an inferior, heavier, bulkier version at about 370,000 credits (+90 lbs, +20% M.D.C., -10% speed, leaping and P.S., -15% prowl; same weapons).', 'ArmaTech lightest power armor: a stealth exoskeleton of metal-ceramic mesh that looks like cloth, linked by nano-systems to implants in the wearer and with an Intel medi-unit that dispenses painkillers, antibiotics, adrenaline and surgical nano-bots. A favorite of recon troops, spies, saboteurs, assassins and agents. It gives more M.D. protection than body armor but less than normal power armor. P.S. 22, nuclear power (10 years), no cargo, usually black with dark blue, green or grey highlights. Forearm vibro-blades and a chest ion gun are built in.', 'Rifts World Book 8: Japan p.143-144'),
  ('h-brand-ninjabot', 'H-Brand "Ninjabot"', 'rifts', 'power-armor', 'One', NULL, 'Running 50 mph (80 kmph) maximum, at 30% of the usual fatigue rate; leaps 10 ft (3.0 m) straight up or lengthwise from a short running start', 'No flying capability; designed for easy attachment of a jet pack', NULL, 'Height 7 ft 5 in (2.2 m); Width 3 ft 6 in (1 m); Length 2.5 ft (0.75 m)', '240 lbs (108 kg)', 190, 1000000, '1 million credits new and undamaged with fully loaded weapons; fair to good availability. Illegal in the Republic of Japan: sold only by criminal organizations, usually about 15% above price, poor availability.', 'A heavy-duty, mass-market power armor from H-Brand, marketed to people fascinated by ninjas and the ArmaTech Power-Spy. Apart from its name, chest ion gun, black color and Japanese styling it has nothing in common with the Power-Spy or with real stealth. Made of light metal and ceramic plating, fully environmental, with a jet pack attachment. Popular with adventurers, street punks, bandits and some mercenaries, rarely with real ninja types. P.S. 25, nuclear power (15 years), no cargo. Special features (printed 146): retractable finger claws; a concealed left-forearm grappling hook and 150 ft (46 m) towline, like the climb cord bionic system; voice-activated electro-adhesive pads in hands and feet that cling to sheer metal-bearing surfaces; and a self-destruct that triggers when the suit detects the pilot has died or on voice command, exploding for 4D6x10 M.D. (add 1D4x10 per mini-missile) in a 60 ft (18.3 m) radius, destroying the armor.', 'Rifts World Book 8: Japan p.144-146'),
  ('ipa-40-dai-katana-bugei', 'IPA-40 Dai-Katana Bugei Power Armor', 'rifts', 'power-armor', 'One', NULL, 'Running 100 mph (160 kmph) maximum (fatigue at 20% of the usual rate); leaps 15 ft (4.5 m) high or lengthwise unassisted, or with the jet pack 80 ft (24.4 m) high and 100 ft (30.5 m) lengthwise', 'Hovers stationary up to 200 ft (61.0 m) or flies; maximum 200 mph (320 kmph), cruising about 60 mph (96 kmph); maximum altitude about 5000 ft (152 m)', NULL, 'Height 6 ft 10 in (2.1 m); Width 3 ft 7 in (1.08 m); Length 3 ft (0.9 m)', '395 lbs (179 kg)', 250, 2000000, '2 million credits for a brand new, undamaged suit with fully loaded weapon systems. Fairly available and in wide use among Ichto and Otomo troops, mercenaries and adventurers; suits regularly go missing from military installations. Illegal in the Republic of Japan, available only from criminal organizations, usually at 25% above the normal price; poor availability there.', 'Ichto''s standard military power armor, a small but tough exoskeleton built for speed, with a jet pack for hovering and limited flight. Its name roughly means ''Great Sword Soldier''. It suits hit and run combat, espionage, anti-terrorism and front-line fighting, and Ichto refits existing suits rather than replace them. Ichto colors are black and grey or dark blue and grey, with red flame-pattern suits for some units, while Otomo uses dark purple and gold. Physical strength equals P.S. 30, nuclear power lasts about 13 years. The jet pack has a five year life but the rockets overheat after about five hours of continuous flight; pushing past that gives a 01-45% chance of burnout, which disables the pack and the armor''s flight until a new unit is installed. Elite RPA pilots gain the listed hand to hand bonuses; Dai-Katana Bugei troops are also trained swordsmen (W.P. sword and paired weapons). Full standard power armor sensors and optics including passive nightvision.', 'Rifts World Book 8: Japan p.146-148'),
  ('ipa-45-ikusa', 'IPA-45 Ikusa (or "Warrior")', 'rifts', 'power-armor', 'One', NULL, 'Running 50 mph (80 kmph) maximum (fatigue only 10% of the usual rate); leaps 15 ft (4.6 m) high or lengthwise with a short running start', NULL, NULL, 'Height 10 ft (3.0 m) head to toe, plus 2 ft (0.6 m) for the horns/blades; Width 4.5 ft (1.4 m); Length 4 ft (1.2 m)', '1100 lbs (495 kg)', 290, 6200000, 'Market Price: 6.2 million credits. The book prints no availability line for the Ikusa. A cheaper knock-off, the H-Brand H-45 Warlord, has 20% less M.D.C., is 20% heavier, costs 10% less and is otherwise identical.', 'A strategic combat power armor styled like ancient samurai armor, with a demonic face plate and four tall blade-like horns on the helmet. Popular with high-tech warriors of Samurai descent, Shoguns, mercenaries and RPA O.C.C.s for its heavy M.D.C., durability and formidable weapons. Its knock-off, the H-Brand Warlord, sold by the thousand until Ichto threatened war over it; Ichto and H-Brand reached an uneasy truce and Ichto destroys knock-offs where it can. Physical strength equals P.S. 34; nuclear power lasts about 20 years; flight is not listed. Armed with a rail gun, mini-missile tubes, a shoulder laser and samurai style vibro-swords that add +1 to strike and parry.', 'Rifts World Book 8: Japan p.148-150'),
  ('ipa-50-grenadier', 'IPA-50 "Grenadier"', 'rifts', 'power-armor', 'One', NULL, 'Running 50 mph (80.46 kmph) maximum (fatigue at 20% of the usual rate); leaps 10 ft (3.0 m) high or lengthwise from a short running start', 'Flight is not possible', NULL, 'Height 9 ft 4 in (2.8 m) head to toe, plus 1 ft (0.3 m) for the shoulder mounted launchers; Width 5 ft 6 in (1.65 m); Length 4 ft 4 in (1.3 m)', '1.3 tons', 580, 16000000, '16 million credits for a brand new, undamaged, fully armed Grenadier. Availability on the Black Market and directly from Ichto is very poor; used prominently by Ichto Robotics'' armed forces. Fewer than 300 sold to the Otomo Shogunate and a few hundred to mercenaries and foreigners, occasionally at twice the usual price; none have gone missing from military installations. Illegal in the Republic of Japan and rarely found even among criminal organizations.', 'A bulky anti-armor assault power armor built to give commandos the firepower to fight dragons and robots, covered in extra plating and bristling with weapon systems. Called a Giant Killer, it has chased off dragons and elementals and done well against Glitter Boys, and some in the Republic of Japan suspect it was designed for that. Its main gun is a huge double-barreled 25 mm grenade launcher; it also carries shoulder, forearm and leg mini-missile launchers and two hand lasers. Physical strength equals P.S. 35; nuclear power lasts about 20 years. Hand to hand: +1D6 M.D. to normal punch or kick, triple damage for power punch or leap kick (two melee attacks), +1 to roll with punch, fall or impact. Standard range of optics, sensors and power armor features.', 'Rifts World Book 8: Japan p.150-152'),
  ('ipa-60-tazu-tengu', 'IPA-60 Tazu-Tengu Power Armor', 'rifts', 'power-armor', 'One', NULL, 'Running 40 mph (64 kmph) maximum (fatigue at 30% of the usual rate); leaps 12 ft (3.65 m) high or lengthwise, or 30 ft (9.2 m) lengthwise with wings extended, unassisted; a jet assisted leap reaches 100 ft (30.5 m) high and 150 ft (45 m) lengthwise, +100 ft lengthwise if the wings are extended to glide', 'Hovers stationary or flies; maximum 350 mph (560 kmph), cruising about 100 mph (160 km); gliding about 60 mph (96 kmph); maximum altitude about 10,000 ft (3048 m); thruster jets need to cool after 10 hours above cruising speed, or 24 hours at cruising speed', NULL, 'Height 7 ft (2.1 m); Width 3 ft 4 in (1.0 m) wings down, 15 ft (4.6 m) wings fully extended; Length 3 ft 8 in (1.1 m)', '220 lbs (100 kg)', 200, 825000, '825,000 credits for a new, undamaged Tazu-Tengu without weapon systems. Good availability; extremely popular among security forces, mercenaries, adventurers and ordinary but wealthy people for travel and recreation; in heavy use by the Ichto and Otomo Shogunates and other kingdoms. Legal in the Republic of Japan but must be officially registered and used safely.', 'A light flying power armor named for the bird-like beings of Japanese myth, built for speed and maneuverability. It has foldable metallic wings, a powerful back thruster, three maneuvering jets in the back and more in the feet, and split-toed claw feet that do 1D6 M.D. each. Its light armor makes it more vulnerable to missile, robot and power armor attack; the IPA-62 is a heavier, slower combat version. Military suits are blue-grey for daytime or jet black for night, civilian suits are bright. Physical strength equals P.S. 24; nuclear power lasts about 16 years. No special hand to hand bonuses or sensor systems beyond the standard light power armor.', 'Rifts World Book 8: Japan p.153-154'),
  ('ipa-62-super-tengu', 'IPA-62 "Super-Tengu"', 'rifts', 'power-armor', 'One', NULL, 'Running 40 mph (64 kmph) maximum (fatigue at 30% of the usual rate); leaps 8 ft (2.4 m) high or lengthwise unassisted; a jet assisted leap reaches 100 ft (30.5 m) high and 150 ft (45 m) lengthwise', 'Hovers stationary or flies; maximum 260 mph (416 kmph), cruising about 100 mph (160 kmph); gliding about 60 mph (96 kmph); maximum altitude about 6000 ft (1828 m); thruster jets need to cool after 10 hours above cruising speed, 24 hours at cruising speed', NULL, 'Height 8 ft (2.1 m) as printed; Width 4 ft (1.2 m) wings down, 16 ft (4.9 m) wings fully extended; Length 4 ft (1.2 m)', '320 lbs (144 kg)', 260, 1200000, '1.2 million credits for a new, undamaged Super-Tengu with basic weapon systems; missiles not included. Fair availability; popular among security forces, mercenaries, adventurers and wealthy civilians; in heavy use by the Ichto and Otomo Shogunates. Illegal in the Republic of Japan, used only by a handful of security forces under official registration and inspection; the Republic''s own military prefers the SAMAS.', 'A heavier version of the IPA-60 Tazu-Tengu that trades speed and mobility for more armor and heavier weapons. It is less heavily armed and armored than suits built for ground combat, and it cannot truly take on fast fighter aircraft or assault helicopters in air to air combat. Used for scouting (a few Tengu ahead of an infantry unit), aerial support and extraction (each can carry one soldier, two if the injuries are light), quick-reaction strikes, seek and destroy, rescue, escort, surveillance, espionage and boarding enemy ships. Physical strength equals P.S. 28; nuclear power lasts about 16 years. Resistant to electricity and electro-magnetic energy (half damage, +3 to save); prowl penalty -25%. A grappling hook and towline (150 ft / 46 m) is in a concealed left forearm housing. No special hand to hand bonuses or sensor systems.', 'Rifts World Book 8: Japan p.155-156');

INSERT OR IGNORE INTO vehicles
  (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, cost, cost_note, description, source_book)
VALUES
  ('ipa-70-mizu-mi', 'IPA-70 Mizu Mi', 'rifts', 'power-armor', 'One', NULL, 'Running 40 mph (64 kmph) maximum (fatigue only 10% of the usual rate); leaps 10 ft (3 m) high or, with a short running start, 15 ft (4.6 m) lengthwise', NULL, 'Swimming 25 mph (40 kmph), fatigue 10%; underwater propulsion system rockets the suit to 50 mph (80 kmph) underwater, 40 mph (64 kmph) surfaced; maximum depth 1.1 miles (1.8 km)', 'Height 9 ft (2.7 m); Width 4.5 ft (1.4 m); Length 4 ft (1.2 m)', '350 lbs (158 kg)', 330, 3100000, '3.1 million credits for a new, undamaged suit. Poor availability.', 'Ichto''s Water Serpent, an all-purpose underwater strategic power armor for exploration, salvage, rescue, mining, scientific study and combat, with an advanced propulsion system and sophisticated sensors. Physical strength equals P.S. 38; nuclear power lasts about 17 years. The pilot can operate 24 hours at maximum efficiency and up to 8 days without food; air is purged and recycled automatically and lasts eight days. A head hit that strips the sensors also risks drowning (oxygen supply lost) or crushing by pressure if deep. Full optics (laser targeting, telescopic, passive nightvision, thermo-imaging, infrared, ultraviolet, polarization) plus a sonar system in place of radar, a depth/pressure gauge, metal detector and mineral analyzer. Hands and feet have electro-adhesive pads for climbing and clinging to metal ship hulls. The standard issue weapon of Republican Navy troopers is the AT-20 Underwater Assault Rifle.', 'Rifts World Book 8: Japan p.156-158'),
  ('at-1053-ka-kuma-metal-bear', 'AT-1053 Ka-Kuma "Metal Bear"', 'rifts', 'robot', 'One pilot, co-pilot/communications/radar operator, and two gunners', 'Two additional passengers, comfortably', 'Running 40 mph (64 km) maximum; cruising about 20 mph (32 km); suitable for most terrains including outer space and underwater, half speed underwater. Leaping not possible', 'Not possible', 'Half ground speed underwater; maximum depth tolerance 2 miles (3.2 km)', 'Height 30 ft (9.1 m); Width 13 ft (4 m); Length 10 ft (3.0 m) not including the long barrels of the rail cannons', '32', 590, 38000000, 'Black market price, 38 million credits for a new, undamaged unit with all weapon systems intact. Fielded by the Republic of Japan''s Armed Forces.', 'The Ka-Kuma, or Metal Bear, is the Republic of Japan''s heavy artillery support infantry robot, bulky and slow like its namesake. Two shoulder rail cannons, each with its own gunner, lob explosive shells out to seven miles, backed by mini-missiles, a forearm missile launcher, a six-barrel rail gun, belly and head energy weapons and flamethrowers. It normally trails the forward infantry and answers radioed fire coordinates, and it doubles as anti-aircraft and anti-monster defense; three Metal Bears with five SAMAS are said to handle one or two dragons or greater elementals. Nuclear powered (17 years), P.S. 50. The left hand is a bear-paw with four large claws. Sensors add long-range radar tracking up to 200 aerial targets, long-range radio and 5 mile (8 km) sonar.', 'Rifts World Book 8: Japan p.158-161'),
  ('at-1063-hi-tora-fire-tiger', 'AT-1063 Hi-Tora "Fire Tiger"', 'rifts', 'robot', 'Three; pilot, co-pilot/communications officer, and a gunner', 'Room for one passenger, a bit cramped', 'Running 60 mph (96.5 km) maximum; cruising about 30 mph (48 km); most terrains including outer space and underwater, half speed underwater; walks upright at half speed; leaping 30 ft (9.1 m) high or lengthwise from standing, double from a running start', 'Not possible', 'Half ground speed underwater; maximum depth tolerance 1.5 miles (2.4 km)', 'Height 22 ft (6.7 m) standing on two legs, 10 ft (3 m) running on all fours; Width 9 ft (2.7 m) shoulder to shoulder; Length 10 ft (3.0 m) standing, 17 ft (5.18 m) on all fours', '18', 500, 32000000, 'Black market price, 32 million credits for a new, undamaged unit with all weapon systems intact. Fielded by the Republic of Japan; completes its robot forces with the SAMAS, Glitter Boys and Ka-Kuma.', 'A fast light infantry support robot built to fight supernatural monsters, which are often vulnerable to fire. It looks like a cross between a giant samurai and a tiger, running on all fours and rising to two legs to fight, climb or work with its human-like hands. Its battery is flame based: a mouth flamethrower, four body flamethrowers, head particle beam blasters and finger lasers, plus chest spray tanks for stench, acid, tear gas, fire retardant foam or water/holy water, and four vibro-blade claws per hand. Nuclear powered (25 years), P.S. 40. Hand to hand bonuses +4 parry, +3 dodge and +2 strike.', 'Rifts World Book 8: Japan p.161-163'),
  ('ir-2015-kani-crab-walker', 'IR-2015 Kani "Crab Walker"', 'rifts', 'robot', 'One pilot; two passengers (usually a co-pilot and communications operator)', 'Two additional passengers can squeeze in, cramped on long journeys', 'Running on dry land 40 mph (64 km) maximum; running underwater 25 mph (40 km) maximum; most terrains including outer space and underwater. Leaping not possible', 'Not possible', 'Thrusters: 30 knots (35 mph/56 km) maximum underwater; on the surface 25.8 knots (30 mph/48 km); maximum depth tolerance 1.2 miles (1.9 km)', 'Height 9 ft (2.7 m) on its legs, 5 ft (1.5 m) legs folded; Width roughly circular, 8 ft (2.4 m) diameter; Length 12 ft (3.65 m) including rear thrusters; Reach of arms 10 ft (3.0 m)', '2.2', 200, 4000000, 'Market price 4 million credits from Ichto; 3.2 million from H-Brand. Used Kani can cost as little as 1.5 million but typically have only 50% of their original M.D.C. H-Brand''s knock-off, the All-Terrain Crawler, has 10% more armor M.D.C., costs 10% less, is 10% slower and has half the depth tolerance. Popular with adventurers, travelers, merchants and fishermen.', 'An Ichto all-purpose three-man work and reconnaissance robot with a disk or clam-shaped body, six crab legs and two forward arms with articulated hands, made for exploration, rescue, labor and salvage on land and under the sea. Legs fold up so it can skim the surface or be driven underwater by four thrusters, and the magnetic foot pads cling to iron hulls. Infrared search lights on flexible stalks with cameras, a laser torch on the right arm and a plasma torch on the left. It fights adequately in light combat but most mercenaries prefer power armor or heavier bots. Nuclear powered (20 years), P.S. 28. Bonuses: +2 dodge (+4 underwater), +2 roll with impact, two attacks per melee plus one at levels six and twelve.', 'Rifts World Book 8: Japan p.164-165'),
  ('ir-2020-wrecker', 'IR-2020 Wrecker', 'rifts', 'robot', 'Two; pilot and co-pilot. Pilots using it for construction and demolition must have the two demolition skills and basic mechanics; the co-pilot is typically an operator/mechanical and/or electrical engineer', 'Room for one passenger, very cramped', 'Running 40 mph (64 km) maximum; suitable for most terrain including outer space and underwater, half speed underwater; leaps 10 ft (3.0 m) high and 20 ft (6.1 m) lengthwise with a short running start; climbing/rappelling 75%/60% (+10% with a climbing skill); digging 3D6x10 ft (9.1 to 56 m) of tunnelling per hour, mining half', 'Not possible', 'Half ground speed underwater', 'Height 24 ft (7.3 m); Width 12 ft (3.5 m); Length 6 ft (1.8 m)', '28', 480, 11000000, '11 million credits new; 7 million reconditioned (1D4x10% less M.D.C.). Replacement small arm 85,000, large arm 195,000, buzz-saw 32,000. H-Brand Battler-1 10 million; Battler-2 (combat version) 14 million; full-modification Battler-3 19 million (50 mph, one forearm laser 2000 ft/610 m range 4D6 M.D., full armor 480 M.D.C.). Optional weapon systems about 1.1 million each, three maximum. Made by Ichto for the mass market; the Republic bought nearly a thousand; never sent into combat by the Republic.', 'Ichto''s mass-market demolition and construction robot, owned by any decent-sized construction firm and bought by the Republic of Japan nearly a thousand of them for civil and military work. Two heavy arms carry giant buzz-saw vibro-blades, the right-hand first finger is a plasma torch, and two small retractable chest arms handle explosives and fine work (one laser torch/welder, one computer jack). A hip compartment holds fusion blocks for placement. Mercenaries and adventurers mount optional lasers, ion cannon or missile launchers. Nuclear powered (20 years), large arms and legs P.S. 48, small arms P.S. 24. H-Brand sells a copy, the Battler-1 (20% less M.D.C.), and a combat Battler-2 with two shoulder ion turrets and a back mini-missile launcher.', 'Rifts World Book 8: Japan p.165-168'),
  ('ir-2040-destroyer', 'IR-2040 Destroyer', 'rifts', 'robot', '1 pilot; no room for passengers', NULL, 'Running 60 mph (96.5 km) maximum; suitable for most terrain including outer space and underwater (half speed underwater). Leaps 10 ft (3.0 m) high or lengthwise standing, 25 ft (7.6 m) with a short running start. Climbing/rappelling 75%/60% (+10% if the pilot has a climbing skill).', 'With the detachable jet backpack: 140 mph (224 km) maximum, altitude 8000 ft (2438.4 m); can hover stationary and helps roll with falls or impact (+2)', 'Half running speed underwater; maximum depth tolerance 1500 ft (457 m)', 'Height 16 ft (4.8 m); Width 5.6 ft (1.7 m); Length 5 ft (1.5 m)', '8', 420, 12000000, '12 million new; 7 million reconditioned/used (has 1D4x10% less M.D.C.); good availability for both. Replacement arms 55,000 credits per small one (frequently destroyed handling explosives) or 155,000 per large one. Military use, also popular with mercenaries, warriors and adventurers.', 'Ichto one-man ground and air assault robot, built for urban and mountain fighting against supernatural monsters, oni and eta wildmen, and fielded by the military and very commonly by mercenaries. It carries shoulder mini-missile launchers, forearm lasers, an IR-60 rail gun and optional hand-held weapons. Two small retractable chest arms handle explosives and fine work (one has a laser torch/welder, the other a computer jack). A detachable jet pack gives it hover and limited flight. P.S. 38 on the large arms and legs, 19 on the small arms; nuclear powered, about 20 years. H-Brand is working on a knock-off (20% less M.D.C., 10% slower, one less attack, 2 million more). Hand to hand: two attacks per melee plus the pilot, +1 attack at levels 5, 10 and 15, plus strike, parry, dodge and roll bonuses.', 'Rifts World Book 8: Japan p.168-170'),
  ('ir-2050-apocalypse', 'IR-2050 Apocalypse', 'rifts', 'robot', '4: pilot, co-pilot/communications officer, and two gunners (one per weapon arm; one also pilots the remote control drone)', NULL, 'Running 40 mph (64 km) maximum; cruising usually about 20 mph (32 km). Suitable for most terrain including outer space and underwater, but swimming and walking speed reduced by half. Leaping not possible.', 'Not possible; its detachable drone (ir-2050-apocalypse-drone) flies', 'Swimming/walking speed halved; maximum depth tolerance 1500 ft (457 m)', 'Height 35 ft (10.7 m) head to toe, 40 ft (12.2 m) including shoulder missile launchers; Width 14 ft (4.3 m); Length 6 ft 8 in (2.0 m)', '50', 625, 68000000, '68 million for a new robot with complete weapon systems. Rarely available on the open market; only from Ichto Robotics. Ichto keeps it in reserve: Otomo Shogunate has 24, Yukamura 10, Toshiie 3, about 50 sold to mercenaries and independent forces.', 'A recent Ichto creation, in service about five years, that Ichto mostly keeps for its own forces but occasionally sells to other kingdoms and mercenaries, which greatly concerns the Republic of Japan, which has placed trade sanctions on it. The 30 ft (9.1 m) robot is a walking arsenal with a demon-face head meant to mock the oni it fights. Besides shoulder and chest missile launchers, forearm lasers, a belly rail gun and a plasma ejector, it has a second pair of weapon arms under the human-like arms, each with a long-range laser, short-range missiles and four blades. The apparent wings and rocket on its back are a detachable remote control VTOL combat drone. P.S. 50, nuclear, 20 years. Special training in piloting the IR-2050 gives the listed hand to hand damage (blade power stab 1D6x10); no bonus list is printed.', 'Rifts World Book 8: Japan p.170-173'),
  ('ir-2050-apocalypse-drone', 'IR-2050 Apocalypse Aerial Combat Drone', 'rifts', 'drone', 'None; remote controlled from the IR-2050', NULL, NULL, '250 mph (400 km); VTOL capable', NULL, 'Height 10 ft (3 m), the body diameter; width 25 ft (7.6 m) with wings fully extended; length 20 ft (6 m)', '4', 110, 1000000, 'One million credits; considered disposable.', 'The remote control aerial combat drone the IR-2050 Apocalypse carries on its back and flies from its cockpit. Control weakens beyond 50 miles (80 km) and is best within 5 miles (8 km); it fights for seven hours on recharged power cells. Only +2 to dodge plus the remote operator''s bonuses (not the robot piloting skill''s). Its weapon arms have P.S. 20.', 'Rifts World Book 8: Japan p.173'),
  ('ir-2060-banshee', 'IR-2060 Banshee', 'rifts', 'robot', '2: pilot and co-pilot/gunner; no room for passengers', NULL, 'Running 60 mph (96 km) maximum; cruising about 25 mph (40 km); half speed underwater; suitable for most terrain including outer space and underwater. Leaps 15 ft (4.6 m) high or lengthwise unassisted; jet-assisted leap up to 100 ft (30.5 m) high and 150 ft (45 m) lengthwise.', 'Hover or fly: maximum 260 mph (416 km), cruising about 100 mph (160 km), gliding about 60 mph (96 km); maximum altitude about 6000 ft (1828 m). Thrusters need to cool after 10 hours of flight above cruising speed, or 24 hours at cruising speed; with 30-60 minute stops they can run indefinitely.', 'Maximum 40 mph (64.3 km) underwater; maximum depth tolerance 2000 ft (610 m)', 'Height 17 ft 8 in (5.4 m); Width 7 ft (2.1 m) shoulder to shoulder; Wings down 10 feet (.03 m) [as printed]; Wings fully extended 30 feet (.19 m) [as printed]; Length 5 ft 4 in (1.6 m) without the shoulder cannon, 9 ft (2.7 m) with it', '22', 400, 28000000, '28 million for a brand new, fully charged robot with complete weapon systems, missiles included (price already lowered 10% by Ichto). Fair to good availability; popular with security forces, mercenaries, adventurers and the wealthy; illegal in the Republic of Japan. Otomo Shogunate has bought 244.', 'Ichto flying infantry robot, in service about two years and already used in dozens of operations to reclaim The Zone; pilots praise it as tough and hard-hitting. It was designed around a prototype sonic cannon on the right or left shoulder, and adds retractable forearm vibro-blades, wrist lasers, clawed fingers and wing mini-missile launchers. It has Tengu-style metal wings on a bulkier skull-headed body, with large back jets, foot thrusters and small maneuvering jets. It is the workhorse of the Otomo Shogunate and is sold on the mass market, straining Ichto relations with the Republic of Japan and Armatech; bandits and Horune pirates have acquired some. P.S. 40, nuclear, 20 years. Sensors are the basic robot set plus sonar.', 'Rifts World Book 8: Japan p.173-176'),
  ('ir-2070-gemini', 'IR-2070 Gemini', 'rifts', 'robot', '1 pilot and a gunner or co-pilot', '1 additional passenger', 'Running 50 mph (80 km) maximum; cruising about 25 mph (40 km); half speed underwater; suitable for most terrain including outer space and underwater. Leaps 10 ft (3.0 m) high or 15 ft (4.6 m) lengthwise; a short running start doubles the distance.', 'Not possible', 'Half running speed underwater', 'Height 21 ft 8 in (6.6 m); Width 8 ft (2.4 m); Length 5 ft 4 in (1.6 m)', '23', 500, NULL, 'Not available on the black market (printed heading is Black Market Price). The book says a prototype reaching the illegal market would retail for 50 million credits or more. Prototype: 24 in field testing with the Ichto Defense Force and a dozen sold to mercenaries active in The Zone.', 'An Ichto prototype still in testing, called the Gemini for its visible face and its invisible blur. Molecular-bonded cloaking armor bends light, making the robot nearly invisible for infiltration, rescue, prisoner snatches and search-and-destroy work, and it can call in artillery or air support while the pilot stays hidden. The body is low-profile with no spikes and is large to hold a big generator. Cloaking halves the range and damage of energy weapons, cuts the power system life from about 20 years to about 6, fails once the main body has lost 70% of its M.D.C., and still leaves a 10% radar chance and a visible shimmer that is worse in close combat, when moving and at night. It stays vulnerable to infrared, thermal, motion and sonar detection, but against most supernatural monsters it is undetectable except at close range. P.S. 45, nuclear. A self-destruct does 2D4x10 M.D. in a 30 ft (9.1 m) radius.', 'Rifts World Book 8: Japan p.176-178');

INSERT OR IGNORE INTO vehicles
  (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, cost, cost_note, description, source_book)
VALUES
  ('ir-4000-tatsu-dragon', 'IR-4000 Tatsu "Dragon"', 'rifts', 'robot', '1 pilot, co-pilot/communications/radar operator, and 2 gunners', '1 additional passenger, comfortably', 'Running 40 mph (64 km) maximum; cruising usually about 20 mph (32 km); suitable for most terrain including outer space and underwater, half speed underwater. Leaping not possible.', 'Not possible', 'Half running speed underwater; maximum depth tolerance 2 miles (3.2 km)', 'Height 20 ft (6.1 m) on all fours, 50 ft (15.2 m) standing erect on rear legs; Width 12 ft (3.65 m), long and narrow; Length about 45 ft (13.7 m) main body, nose to hind legs, plus a 60 ft (18.3 m) flexible prehensile tail, overall 105 ft (32.0 m)', '132', 1000, NULL, 'Not available (printed heading is Black Market Price). Costs 750 million credits to build each one. Used exclusively by the Ichto Robotics Corporation: 16 active, 4 under repair, 24 more planned over two years, 4 destroyed and 1 missing.', 'Ichto giant armored robot dragon, built to out-do Armatech dragon-borgs and looking like an oriental dragon in overlapping scale plates with spiny ridges and three horns on the head. It is about three times the size of a real Japanese dragon or dragon borg and has fought a great horned dragon toe to toe. Only Ichto uses it, to defend the province and its holdings. It has mouth weapons (a plasma thrower and a plasma cannon), nostril mini-missile launchers, a bite and horns, palm lasers, a shoulder missile launcher for the gunners, a double-barreled tail laser and a prehensile tail with P.S. 50. P.S. 50 overall, nuclear power lasting about 25 years; sensors are the full robot array and optics plus long-range communications, radar and sonar. Hand to hand: three attacks per melee plus the pilot, +1 at levels 5, 10 and 15; kicks are not possible.', 'Rifts World Book 8: Japan p.178-181');

