INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note)
VALUES
  ('at-samurai-samas-pa-10a', 1, 'AT-P1000 SAMAS Particle Beam Rifle', 'Particle beam 1D6x10 M.D. per blast; laser 3D6 M.D.', 1, 'P-beam 2000 ft (610 m); laser 1600 ft (488 m)', 'Equal to the number of combined hand to hand attacks (usually 4-6); each blast is one melee action; laser and P-beam cannot fire together', 'Effectively unlimited while cabled to the power supply; if the cables (6 M.D.C. each) are cut, 3D4 charges; or 10 shots per standard E-clip', NULL, 'Weight 42 lbs (18.9 kg). The scope-like item is a short-range laser. Rail guns and other weapons may be substituted.'),
  ('at-samurai-samas-pa-10a', 2, 'AT-M2 Rocket Launchers (2)', 'Varies with missile type; standard armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.; AT-AAD dissolver and stun types also common', 1, 'About a mile (1.6 km)', 'One or two', 'Four; two per forearm', NULL, 'Mini-missile launchers in each forearm.'),
  ('at-samurai-samas-pa-10a', 3, 'AT-N20 Neural Stick (1)', '1D6 S.D.C. plus P.S. bonus as a club; stun effect (victim saves vs non-lethal poison/attack at 16 or higher)', 0, NULL, NULL, NULL, NULL, 'Stun: failed save = -7 initiative, -5 strike/parry/dodge, halved attacks/speed/skills for 2D4 melees, +2D4 melees and 15% cumulative chance of unconsciousness 1D4 minutes per extra hit. Ineffective against environmental body armor, power armor, full conversion borgs, robots, androids. Parries S.D.C. and M.D. weapons. Carried with a sidearm (stun-gun, laser pistol or vibro-katana 3D6 M.D.).'),
  ('at-samurai-samas-pa-10a', 4, 'Hand to Hand Combat', 'Mega-damage per Power Armor Combat Training, Rifts RPG p.45 (damage not printed here)', 1, 'Hand to hand', NULL, NULL, 'Sensor bonuses (long range only): +2 to strike, +1 to dodge', 'Book item 5. Book item 4 (Energy Rifles and other weapons may be substituted; limited to one additional handgun or rifle) is not a row.'),
  ('usa-g10a1-point-glitter-boy', 1, 'Multi-Barrel Laser Rifle (M-BiLAR) AT-5000', '4D6 M.D. per double blast; 1D4x10+8 M.D. per quadruple blast; 1D6x10 M.D. per full five-barrel pulse', 1, '6000 ft (1830 m)', 'Equal to the combined number of hand to hand attacks (usually 4-6)', 'Effectively unlimited (tied to the nuclear power supply)', '+2 to strike on aimed shots only (advanced laser targeting)', 'Weight 289 lbs (131 kg). Slung on the back; silent, no kick.'),
  ('usa-g10a1-point-glitter-boy', 2, 'AT-200 III Rail Gun (1)', 'Full burst of 30 rounds 6D6 M.D.; short burst of 15 rounds 3D6 M.D.', 1, '3000 ft (914 m)', 'Equal to the combined hand to hand attacks of pilot and armor (usually 4-6)', '3300 rounds (110 full bursts) in an internal drum; reload about 5 minutes with technicians and equipment, not possible in combat', NULL, 'Weight 68 lbs (31 kg). Left forearm, tri-barrel.'),
  ('usa-g10a1-point-glitter-boy', 3, 'Smoke Dispensers (2)', 'None; concealment', 0, '80 ft (24.4 m)', '1, 2, 3 or 4 at a time', '4 smoke grenades total; 2 in each leg', NULL, 'Smoke covers a circle about 80 ft (24.4 m) across.'),
  ('usa-g10a1-point-glitter-boy', 4, 'Hand to Hand Combat', 'Mega-damage per Power Armor Combat Training, Rifts RPG pp.44-45 (damage not printed here)', 1, 'Hand to hand', NULL, NULL, '+1 initiative, +2 roll with punch or impact; no prowl penalty except when camouflage is removed (-15%)', 'Book item 4; book item 5 (sensor systems) is in the description.'),
  ('usa-g10a1-point-glitter-boy', 11, 'Optional: Underwater M-BiLAR AT-5500', '4D6 M.D. per double blast; 1D4x10+8 M.D. per quadruple blast; 1D6x10 M.D. per full five-barrel pulse', 1, 'Underwater 2200 ft (670.5 m); 5000 ft (1520 m) in atmosphere', 'Equal to the combined number of hand to hand attacks (usually 4-6)', 'Effectively unlimited', '+2 to strike on aimed shots only', 'Optional GB Weapon Systems item 2, printed 142. Underwater version using blue-green beams, for the G10 and G10A1. Weight 289 lbs (131 kg). A replacement for the main gun.'),
  ('usa-g10a1-point-glitter-boy', 12, 'Optional: AT-1800 All-Purpose Rail Gun', 'Burst of 50 rounds 1D6x10+10 M.D.', 1, '6000 ft (1828 m)', 'Equal to the combined number of hand to hand attacks (usually 4-6)', '9000 rounds (180 bursts); reload a drum about 5 minutes untrained, 1 minute by a power-armor-trained user with P.S. 26+', NULL, 'Optional GB Weapon Systems item 1, printed 142: may replace the standard main gun of any Glitter Boy. Weight 475 lbs (215 kg). No kick or sonic blast.'),
  ('usa-g10a1-point-glitter-boy', 13, 'Optional: GMS-APM Launcher', 'Varies with missile type; standard fragmentation 5D6 M.D., or stun and smoke for riot control', 1, 'Usually about 1 mile (1.6 km)', 'One at a time, or volleys of two, four, six or 12', '48 per launcher; reload 1D4+2 minutes', NULL, 'Optional GB Weapon Systems item 3, printed 142: 12-slot mini-missile launcher above the right shoulder in place of the main gun, jettisonable.'),
  ('usa-g10a2-hawkeye-glitter-boy', 1, 'Multi-Barrel Laser Rifle (M-BiLAR) AT-5000', '4D6 M.D. per double blast; 1D4x10+8 M.D. per quadruple blast; 1D6x10 M.D. per full five-barrel pulse', 1, '6000 ft (1830 m)', 'Equal to the combined number of hand to hand attacks (usually 4-6)', 'Effectively unlimited (tied to the nuclear power supply)', '+2 to strike on aimed shots only (advanced laser targeting)', 'Weight 289 lbs (131 kg). Same gun as the Point; no kick.'),
  ('usa-g10a2-hawkeye-glitter-boy', 2, 'GMS-24 Medium-Range Missile Launcher', 'High explosive 2D6x10 M.D.; plasma/heat 3D6x10 M.D.; fusion 4D6x10 M.D.', 1, '21 miles (33.7 km) for each missile type', 'One at a time, or volleys of two or four', '24 total', 'Smart bombs, +5 to strike', 'Replaces the ammo drum and stabilizer jets. Range printed as 33.7 kg in the book, a typo for km.'),
  ('usa-g10a2-hawkeye-glitter-boy', 3, 'GMS-SAM Launcher (1)', 'Varies with missile type; standard armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.', 1, 'Varies with missile type', 'One at a time, or volleys of two, four and six', '24 total', NULL, 'Box-style heat-seeking mini-missile launcher on the left shoulder, for low-flying targets; voice or trigger launch.'),
  ('usa-g10a2-hawkeye-glitter-boy', 4, 'GMS-FAM Launcher (2)', 'Varies with missile type; standard armor piercing 1D4x10 M.D., plasma 1D6x10 M.D., or AAD-Dissolvers (anti-armor)', 1, 'Varies with missile type', 'One at a time, or volleys of two, four and six', 'Six total; three per arm', NULL, 'A pair of mini-missile launchers built into each forearm.'),
  ('usa-g10a2-hawkeye-glitter-boy', 5, 'Hand to Hand Combat', 'Mega-damage per Power Armor Combat Training, Rifts RPG pp.44-45 (damage not printed here)', 1, 'Hand to hand', NULL, NULL, '+3 initiative (extended radar), +1 roll with punch, fall or impact', NULL),
  ('usa-g10a2-hawkeye-glitter-boy', 11, 'Optional: AT-1800 All-Purpose Rail Gun', 'Burst of 50 rounds 1D6x10+10 M.D.', 1, '6000 ft (1828 m)', 'Equal to the combined number of hand to hand attacks (usually 4-6)', '9000 rounds (180 bursts); reload a drum about 5 minutes untrained, 1 minute by a power-armor-trained user with P.S. 26+', NULL, 'Optional GB Weapon Systems item 1, printed 142: may replace the standard main gun of any Glitter Boy. Weight 475 lbs (215 kg).'),
  ('usa-g10a2-hawkeye-glitter-boy', 12, 'Optional: GMS-APM Launcher', 'Varies with missile type; standard fragmentation 5D6 M.D., or stun and smoke for riot control', 1, 'Usually about 1 mile (1.6 km)', 'One at a time, or volleys of two, four, six or 12', '48 per launcher; reload 1D4+2 minutes', NULL, 'Optional GB Weapon Systems item 3, printed 142: 12-slot mini-missile launcher above the right shoulder in place of the main gun, jettisonable.'),
  ('atpa-85-power-spy', 1, 'AT-85 Ion Gun', '4D6 M.D. per blast', 1, '800 ft (244 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, NULL),
  ('atpa-85-power-spy', 2, 'Vibro-Blades (2)', '2D6 M.D.', 1, 'Hand to hand', NULL, NULL, '+1 to strike, +2 to parry', 'Long retractable vibro-swords built into both forearms.'),
  ('atpa-85-power-spy', 3, 'Energy Rifles, Rail Guns or Other Hand Weapons', 'By weapon', 1, NULL, NULL, NULL, NULL, 'Carried, not built in; officers also wear a sidearm.'),
  ('atpa-85-power-spy', 4, 'Hand to Hand Combat', 'Normal punch 1D4 M.D.; power punch 2D4 M.D. (counts as two attacks); leap kick 2D6 M.D.', 1, NULL, NULL, NULL, 'As Basic/Elite Power Armor Combat Training (Rifts RPG p.45), plus +1 to dodge and roll at level five, +2 to pull punch, and no power armor prowl penalty', NULL),
  ('h-brand-ninjabot', 1, 'H-85 Ion Gun', '4D6 M.D. per blast', 1, '800 ft (244 m)', 'Equal to the number of combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Chest mounted, barrel rotates 45 degrees; a cheap imitation of the Power-Spy ion gun. Primary purpose defense.'),
  ('h-brand-ninjabot', 2, 'Vibro-Blade (1)', '2D6 M.D.', 1, 'Hand to hand', NULL, NULL, '+1 to strike, +2 to parry', 'Retractable vibro-sword in the right forearm.'),
  ('h-brand-ninjabot', 3, 'Mini-Missile Tube Launchers (6)', 'Varies with missile type, usually 1D4x10 M.D. or 1D6x10 M.D.', 1, 'One mile (1.6 km)', 'One at a time, or in volleys of two', 'Six total', NULL, 'Six tube launchers in the oversized left shoulder plate, one mini-missile each. Primary purpose assault, secondary defense. Tail read from printed 146.'),
  ('h-brand-ninjabot', 4, 'Energy Rifles, Rail Guns or other hand weapons', 'By weapon used', 1, NULL, NULL, NULL, NULL, 'Weapons vary with the pilot; vibro-swords and energy rifles are most common. Book item 4; not a built-in system.'),
  ('h-brand-ninjabot', 5, 'Hand to Hand Combat', '+1D6 M.D. to slashing and tearing attacks (retractable finger claws)', 1, 'Hand to hand', NULL, NULL, '+1 to parry, +1 to pull punch; otherwise as Basic/Elite Power Armor Combat Training (Rifts RPG p.45)', NULL),
  ('ipa-40-dai-katana-bugei', 1, 'IR-60 Rail Gun', 'Full burst (40 rounds) 1D4x10 M.D.; 10-shot burst 2D6 M.D.', 1, '4000 ft (1220 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', '2400 rounds per drum, 60 full bursts', NULL, 'Primary purpose: assault. Gun 90 lbs (40.8 kg), drum 120 lbs (54 kg); a reserve clip (usually silver ammo vs supernatural) is on the gun. Reloading a drum takes about 5 minutes untrained, 1 minute trained, P.S. 26+ required. Printed as ''the Kantana''s standard armament'' (book slip).'),
  ('ipa-40-dai-katana-bugei', 2, 'Shoulder Mini-Missile Launchers (2)', 'Varies with missile type; usually 1D4x10 M.D. (armor piercing) or 1D6x10 M.D. (plasma); fragmentation 5D6 M.D.', 1, 'About a mile (1.6 km)', 'One at a time or in volleys of two or three', 'Six total, three per launcher', NULL, 'Primary purpose: anti-armor and assault, secondary: anti-aircraft. Reloading needs a second person and takes about a minute.'),
  ('ipa-40-dai-katana-bugei', 3, 'VL-40 Head Laser (1 or 2)', '2D6 M.D. per single blast; 4D6 M.D. from two', 1, '1000 ft (305 m)', 'Standard', 'Unlimited (drawn from the nuclear power supply)', NULL, 'Primary purpose: defense. Grunts and low ranking officers have one laser, high ranking officers and Special Forces two. Fired by voice or a button.');

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note)
VALUES
  ('ipa-40-dai-katana-bugei', 4, 'Retractable Vibro-Katanas (2)', '4D6 M.D. each', 1, 'Hand to hand (3 ft / 0.9 m blades)', NULL, NULL, NULL, 'Primary purpose: defense and close combat; also assassination and silent attacks. One on each forearm.'),
  ('ipa-40-dai-katana-bugei', 5, 'Forearm Blades (2)', '1D6 M.D. each', 1, 'Hand to hand', NULL, NULL, NULL, 'Primary purpose: defense; slashing and jabbing, parrying vibro-weapons without extending the vibro-blades.'),
  ('ipa-40-dai-katana-bugei', 6, 'Energy Rifles, Light Rail Guns', 'Not given', 0, NULL, NULL, NULL, NULL, 'Hand-held weapons usable as a substitute for the standard rail gun; light weapons often preferred for espionage and special missions.'),
  ('ipa-40-dai-katana-bugei', 7, 'Hand to Hand Combat', 'Mega-damage hand to hand per Rifts RPG p.45 (no damage figures printed here)', 1, 'Hand to hand', NULL, NULL, 'Elite RPA O.C.C. training plus: +1 initiative, +2 to pull punch, +1 to parry and dodge, +1 attack per melee at level three, no prowl penalties (other characters use Basic Power Armor Combat bonuses). W.P. sword and paired weapons.', 'Bonuses for Dai-Katana Bugei power armor combat training.'),
  ('ipa-45-ikusa', 1, 'IR-70 Rail Gun', 'Full burst (40 rounds) 1D6x10 M.D.; 10-shot burst 3D6 M.D.', 1, '4000 ft (1220 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', '3200 round drum for 80 bursts; clip magazine 200 rounds (5 full bursts)', NULL, 'Primary purpose: assault. Stowed on the back above and behind the right shoulder and pulled forward when needed. Reload a drum about 5 minutes untrained, 1 minute trained, P.S. 26+.'),
  ('ipa-45-ikusa', 2, 'Mini-Missile Launchers (8)', 'Varies with missile type; any type, standard issue armor piercing 1D4x10 M.D. or plasma/Heavy-Hitters 1D6x10 M.D.; fragmentation or concussion 5D6 M.D.', 1, 'Usually about a mile (1.6 km)', 'One at a time, or in volleys of two or three', 'Eight; each tube takes about 10 seconds to reload manually', NULL, 'Several one-shot tubes along the entire length of the left arm; can fire while holding or using the vibro-swords. Primary purpose: anti-armor/assault, secondary: defense.'),
  ('ipa-45-ikusa', 3, 'Shoulder Laser (1)', '3D6 M.D. per blast', 1, '1200 ft (365.7 m)', 'Standard', 'Effectively unlimited', NULL, 'Primary purpose: anti-personnel, secondary: defense. Mounted on the left shoulder; rotates 180 degrees with a 60 degree arc of fire.'),
  ('ipa-45-ikusa', 4, 'Vibro-Swords (2)', 'Giant Wakazashi 3D6 M.D.; Giant Katana 5D6 M.D.', 1, 'Hand to hand', NULL, NULL, '+1 to strike and parry', 'A daisho of vibro-swords; can parry M.D. attacks including energy blasts (-6 to parry), arrows and missiles (-4 to parry).'),
  ('ipa-45-ikusa', 5, 'Energy Rifles, Rail Guns', 'Not given', 0, NULL, NULL, NULL, NULL, 'Other hand weapons can be used instead of or in addition to the standard armaments.'),
  ('ipa-45-ikusa', 6, 'Hand to Hand Combat', 'Restrained Punch 1D4 M.D.; Normal Punch or Kick 2D6 M.D.; Power Punch 4D6 M.D. (two melee attacks); Leap Kick 3D6 M.D. (two melee attacks); Body Flip/Throw 1D6 M.D.; Body Block/Tackle 2D4 M.D.', 1, 'Hand to hand', NULL, NULL, 'As Basic and Elite Power Armor Combat Training (Rifts RPG p.45); no extra bonuses printed', NULL),
  ('ipa-50-grenadier', 1, 'IR-50 "Super-Launcher" (1)', 'Per grenade: Fragmentation (antipersonnel, light) 2D6 M.D. in a 20 ft (6.1 m) radius, 200 credits each; Heavy Fragmentation 3D6 M.D. in a 30 ft (9.1 m) radius, 250 credits; High Explosive (anti-armor) 4D6 M.D. in a 6 ft (1.8 m) area, 150 credits; Plasma 5D6 M.D. in a 12 ft (3.65 m) area, 350 credits. Multiply damage by the number of grenades fired in a burst; blast radius grows only 5% per grenade.', 1, '1600 ft (488 m)', 'One at a time or rapid succession like an automatic rifle; bursts of two, four or a maximum of eight grenades fire within a split second; each burst counts as one melee attack', '200; ammo drum split into two magazines of 100 rounds each', NULL, 'Primary purpose: assault, secondary: anti-armor. Huge double-barreled, fully automatic 25 mm grenade launcher with a belt feed, the Grenadier''s main gun. Other grenade types (stun/flash, tear gas, concussion, smoke, AAD-Dissolvers) are usable; AAD-Dissolvers are scarce outside the Black Market. Waist belt/bandoleer: 6 to 8 grenades on the chest belt plus four pouches of 6 on the waist belt; a pack or sack can hold another 20 to 40.'),
  ('ipa-50-grenadier', 2, 'Shoulder Mini-Missile Launchers (2)', 'Varies with missile type; any type, standard issue armor piercing 1D4x10 M.D. or plasma/Heavy-Hitters 1D6x10 M.D.; fragmentation and concussion seldom used', 1, 'Usually about a mile (1.6 km)', 'One at a time, or in volleys of two, three, four or six', '12 total, 6 per shoulder', NULL, 'Primary purpose: anti-armor, secondary: assault. Two launch tubes on each shoulder contain the mini-missiles.'),
  ('ipa-50-grenadier', 3, 'Forearm Mini-Missile Launcher (1)', 'Varies with missile type; standard issue heat-seeking Heavy-Hitters 1D6x10 M.D. or plasma 1D6x10 M.D.', 1, 'Usually about a mile (1.6 km)', 'One at a time, or a volley of two', 'Three', 'Heat-seeking missiles +5 to strike', 'Primary purpose: anti-aircraft. Three-shot launcher atop the left forearm (right for left-handed pilots).'),
  ('ipa-50-grenadier', 4, 'Leg Mini-Missile Launchers (4)', 'Varies with missile type; standard issue armor piercing 1D4x10 M.D. or plasma/Heavy-Hitters 1D6x10 M.D.; fragmentation and concussion seldom used', 1, 'Usually about a mile (1.6 km)', 'One at a time, or volleys of two, three or four', '16 total, 4 per launcher', NULL, 'Primary purpose: anti-armor, secondary: assault. Small launchers on the calf and thigh of each leg, four mini-missiles each.'),
  ('ipa-50-grenadier', 5, 'Hand Lasers (2)', '2D6 M.D. per blast; simultaneous double blasts not possible', 1, '1200 ft (365 m)', 'Standard', 'Effectively unlimited', NULL, 'Primary purpose: defense, secondary: anti-armor/armor cutting. Short-range lasers built into the top of each hand; also a tool.'),
  ('ipa-50-grenadier', 6, 'Large energy rifles, rail guns', 'Not given', 0, NULL, NULL, NULL, NULL, 'Usable by the giant Grenadier but seldom issued or suggested.'),
  ('ipa-50-grenadier', 7, 'Hand to Hand Combat', '+1D6 M.D. to normal punch or kick; triple damage from power punch or leap/jump kick (counts as two melee attacks)', 1, 'Hand to hand', NULL, NULL, '+1 to roll with punch, fall or impact; plus Basic or Elite Power Armor Combat bonuses (Rifts RPG p.45)', 'Fingers are thick and designed to puncture and tear apart armor.'),
  ('ipa-60-tazu-tengu', 1, 'Grenades/Bombs', 'Fragmentation (antipersonnel, light) 2D6 M.D. in a 20 ft (6.1 m) radius, 200 credits each; Heavy Fragmentation 3D6 M.D. in a 30 ft (9.1 m) radius, 250 credits; High Explosive (anti-armor) 4D6 M.D. in a 6 ft (1.8 m) area, 150 credits; Plasma 5D6 M.D. in a 12 ft (3.65 m) area, 350 credits', 1, 'Thrown 200 ft (61 m), augmented by the armor''s strength; 500 ft (152 m) when dropped from the sky; -2 to strike for each additional 100 ft (30.5 m) of height', 'Typically one or two are used/dropped on a target at a time; each throw or drop counts as one melee attack', 'Typically approximately 32 hand grenades', NULL, 'Primary purpose: assault, secondary: anti-armor. Other grenade types (stun/flash, tear gas, concussion, smoke, AAD-Dissolvers) are usable; AAD-Dissolvers are scarce outside the Black Market. Waist belt/bandoleer: 6 to 8 grenades on the chest belt plus four pouches of 6 on the waist belt; a pack or sack can hold another 20 to 40.'),
  ('ipa-60-tazu-tengu', 2, 'Energy Rifles, Rail Guns', 'Not given', 0, NULL, NULL, NULL, NULL, 'Other hand-held weapons usable by the man-sized armor; laser rifles are most popular (silent, excellent range); sidearm/pistol and vibro-blades also common.'),
  ('ipa-60-tazu-tengu', 3, 'Hand to Hand Combat', 'Mega-damage hand to hand per Rifts RPG p.45; feet have raking claws 1D6 M.D. per foot (printed in the intro)', 1, 'Hand to hand', NULL, NULL, 'None special (Basic and Elite Power Armor Combat Training, Rifts RPG p.45)', NULL),
  ('ipa-62-super-tengu', 1, 'Mini-Missile Launcher (1)', 'Varies with missile type; any type usable', 1, 'Approximately one mile (1.6 km)', 'One at a time, or in volleys of two, three or four', '12 mini-missiles', NULL, 'Primary purpose: anti-aircraft/armored vehicle, secondary: assault. On the back between the wings above the jet thruster.'),
  ('ipa-62-super-tengu', 2, 'Grenades/Bombs', 'Varies with grenade type; same as the Tazu-Tengu: Fragmentation (antipersonnel, light) 2D6 M.D. in a 20 ft (6.1 m) radius, 200 credits each; Heavy Fragmentation 3D6 M.D. in a 30 ft (9.1 m) radius, 250 credits; High Explosive (anti-armor) 4D6 M.D. in a 6 ft (1.8 m) area, 150 credits; Plasma 5D6 M.D. in a 12 ft (3.65 m) area, 350 credits', 1, 'Thrown 200 ft (61 m), augmented by the armor''s strength; 500 ft (152 m) when dropped from the sky; -2 to strike for each additional 100 ft (30.5 m) of height', 'Typically one or two used/dropped on a target at a time; each throw or drop counts as one melee attack', 'Typically approximately 32 hand grenades', NULL, 'Primary purpose: assault, secondary: anti-armor. Same waist belt and bandoleer arrangement as the Tazu-Tengu.'),
  ('ipa-62-super-tengu', 3, 'Forearm Lasers (2)', '3D6 M.D. per single blast; 6D6 M.D. per double blast', 1, '1200 ft (365 m)', 'Equal to the number of combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Primary purpose: defense. Small short-range tactical lasers built into each forearm.'),
  ('ipa-62-super-tengu', 4, 'Energy Rifles, Rail Guns', 'Not given', 0, NULL, NULL, NULL, NULL, 'Laser rifles most popular; sidearm/pistol and vibro-blades also common.'),
  ('ipa-62-super-tengu', 5, 'Hand to Hand Combat', 'Mega-damage hand to hand per Rifts RPG p.45', 1, 'Hand to hand', NULL, NULL, 'None special', NULL),
  ('ipa-70-mizu-mi', 1, 'AT-70 Blue-Green Laser Weapon (1)', '2D6 M.D. per blast', 1, '500 ft (152 m) underwater or 1000 ft (305 m) in an atmosphere', 'Equal to the combined number of hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Primary purpose: defense. Small twin-barreled laser above the right shoulder; barrels rotate 45 degrees in any direction.'),
  ('ipa-70-mizu-mi', 2, 'Shoulder Mounted Mini-Torpedo Launcher (1)', '1D6x10 M.D.; standard equal mix of high explosive and plasma mini-torpedoes (1D6x10 M.D.)', 1, 'One mile (1.6 km)', 'One at a time, or in volleys of two, three or four', '10 mini-torpedoes', NULL, 'Primary purpose: defense, secondary: anti-sub/assault. On the left shoulder.'),
  ('ipa-70-mizu-mi', 3, 'AT-90F Plasma Cutter (1)', 'Three settings: 1D6 M.D., 3D6 M.D. and 6D6 M.D. per blast', 1, '12 ft (3.65 m)', 'Equal to the combined number of hand to hand attacks (usually 4-6)', '50 blasts', NULL, 'Primary purpose: tool and rescue, secondary: defense. Atop the right forearm; a mining, salvage and rescue tool usable as a close combat weapon.'),
  ('ipa-70-mizu-mi', 4, 'RVB-70 Vibro-Cutter', '1D6 M.D.', 1, 'Hand to hand', NULL, NULL, NULL, 'Short, broad, flat retractable vibro-blade housed in the left forearm; a digging and cutting tool usable as a weapon.'),
  ('ipa-70-mizu-mi', 5, 'Energy Rifles, Harpoon Launchers', 'Not given', 0, NULL, NULL, NULL, NULL, 'Other hand weapons usable easily; standard issue of Republican Navy troopers is the AT-20 Underwater Assault Rifle; officers also get a waist belt with holster and energy sidearm.');

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note)
VALUES
  ('ipa-70-mizu-mi', 6, 'Hand to Hand Combat', 'Restrained Punch 6D6 S.D.C.; Full Strength Punch 2D6 M.D.; Power Punch 4D6 M.D. (counts as two attacks); Crush, Pry or Tear 2D4 M.D.', 1, 'Hand to hand', NULL, NULL, '+1 to dodge; +4 underwater; +2 to roll with impact', 'Restrained punch is S.D.C. damage, the other modes M.D. Otherwise as Basic and Elite Power Armor Combat Training, Rifts RPG p.45.'),
  ('at-1053-ka-kuma-metal-bear', 1, 'AT-1053 Rail Cannons (2)', 'Fragmentation (30 lbs) 2D6x10 M.D., blast radius 80 ft (24.4 m); High Explosive (20 lbs) 3D4x10 M.D., blast radius 30 ft (9.1 m); Plasma (40 lbs) 3D6x10 M.D., blast radius 50 ft (15.2 m); Nuclear (50 lbs) 4D6x10 M.D., blast radius 100 ft (30.5 m); smoke and tear gas/riot control rounds do no damage', 1, '7 miles (11.2 km); cannot fire at targets closer than 1000 ft (305 m) unless giant-sized (15 ft+), or directly above or below', 'Four total per melee round; 2 shots per gun per melee (each gun has its own gunner)', '100 explosive rounds total, 50 per cannon; usual mix 40 Fragmentation, 10 HE, 25 Plasma, 25 Nuclear, any combination allowed', NULL, 'Indirect fire support; secondary anti-armor/assault. Each rotates 90 degrees in all directions and locks in position. Shells are 20-50 lbs. Text prints the model as AT-1503 in this entry.'),
  ('at-1053-ka-kuma-metal-bear', 2, 'Shoulder Mini-Missile Launchers (2)', 'Varies with missile type; standard armor piercing 1D4x10 M.D., plasma or Heavy-Hitters 1D6x10 M.D.', 1, 'About a mile (1.6 km)', 'One at a time, or volleys of two, three or four', '24; 12 in each launcher', NULL, 'Primary defense, secondary anti-armor/assault. Controlled exclusively by the gunners.'),
  ('at-1053-ka-kuma-metal-bear', 3, 'Forearm Short-Range Missile Launcher (1)', 'Varies with missile type; standard load armor piercing 1D6x10 M.D. or plasma 1D6x10 M.D.', 1, 'Varies with missile type', 'One at a time, or volleys of two', 'Four total', 'Heat-seeking missiles +5 to strike once locked on', 'Left forearm, four-shot; primary anti-aircraft; fired by pilot or co-pilot. Standard load is heat-seeking.'),
  ('at-1053-ka-kuma-metal-bear', 4, 'AT-2400 Rail Gun (1)', 'A burst is 60 rounds: 2D4x10 M.D.', 1, '6000 ft (1830 m)', 'Standard; bursts or wild fire only', '9000-round drum on the back (150 bursts); an identical second magazine feeds when the first is empty: 18,000 rounds (300 bursts) total. Drums need specialized equipment and 5 minutes each to reload; cannot be reloaded in the field', NULL, 'Right forearm, six-barrel gatling style; silver ammunition can be substituted. Primary defense, secondary assault; fired by pilot or co-pilot.'),
  ('at-1053-ka-kuma-metal-bear', 5, 'Belly Laser Turret (1)', '3D6 M.D. per single blast or 6D6 M.D. per dual simultaneous blast', 1, '4000 ft (1220 m)', 'Equal to the combined hand to hand attacks of the pilot or co-pilot (usually 4-6)', 'Effectively unlimited', NULL, 'Double-barreled; swings 120 degrees side to side and 90 up and down. Operated by a gunner or the co-pilot. Location table prints it as Laser Belly Gun (1).'),
  ('at-1053-ka-kuma-metal-bear', 6, 'Flamethrowers (2)', '1D4 M.D. per single blast or 2D4 M.D. per dual simultaneous blast of napalm-like fire; 01-90% chance of igniting combustibles, which take an additional 1D4 M.D. per melee and burn a minimum of 2D4 minutes', 1, '200 ft (61.0 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', '50 blasts total, 25 from each leg', NULL, 'One in the lower portion of each leg, in a turret rotating 45 degrees any direction. Primary removal of obstacles, secondary anti-personnel/anti-monster. Any crew member can fire.'),
  ('at-1053-ka-kuma-metal-bear', 7, 'Light Particle Beam Head Blasters (2)', '1D4x10 M.D. per single blast or 2D4x10 M.D. per dual simultaneous blast', 1, '1200 ft (365 m)', 'Equal to the combined hand to hand attacks of the operator (usually 4-6)', 'Effectively unlimited', NULL, 'One in each eye; head rotates 120 degrees side to side and 60 up and down. Primary defense, secondary assault; gunner or co-pilot.'),
  ('at-1053-ka-kuma-metal-bear', 8, 'Hand to Hand Combat', 'Restrained Punch 1D6 M.D.; Full Strength Punch 3D6 M.D.; Power Punch/Stab/Slash 1D6x10 M.D. (counts as two attacks); Crush, Pry or Tear 1D6 M.D.; Body Flip/Throw 1D6 M.D.; Body Block/Ram 2D4 M.D.; Stomp 2D4 M.D. against man-sized targets; Kick not possible (too unbalanced)', 1, 'Hand to hand', NULL, NULL, 'All abilities as the UAR-1 Enforcer (Rifts RPG p.44-45) except as listed', 'Left hand is a shovel-shaped paw with four large claws/spikes.'),
  ('at-1063-hi-tora-fire-tiger', 1, 'Mouth Flamethrower (1)', '3D6 M.D. per single blast of napalm-like fire; 01-90% chance of igniting combustibles, which take an additional 1D4 M.D. per melee and burn a minimum of 2D4 minutes', 1, '200 ft (61.0 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', '50 blasts total', NULL, 'Primary anti-monster, secondary anti-personnel.'),
  ('at-1063-hi-tora-fire-tiger', 2, 'Flamethrowers (4)', '1D4 M.D. per single blast or 2D4 M.D. per dual simultaneous blast of napalm-like fire; 01-90% chance of igniting combustibles, additional 1D4 M.D. per melee, burns a minimum of 2D4 minutes', 1, '200 ft (61.0 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', '100 blasts total, 25 from each shoulder and leg', NULL, 'One in each shoulder and hip, in 45-degree turrets; any crew member can fire. Primary removal of obstacles, secondary anti-personnel/anti-monster. Location table lists only Shoulder Flamethrowers (2) at 40 each.'),
  ('at-1063-hi-tora-fire-tiger', 3, 'Light Particle Beam Head Blasters (2)', '1D4x10 M.D. per single blast or 2D4x10 M.D. per dual simultaneous blast', 1, '1200 ft (365 m)', 'Equal to the combined hand to hand attacks of the operator (usually 4-6)', 'Effectively unlimited', NULL, 'One in each eye; head rotates 120 degrees side to side and 60 up and down. Primary defense, secondary assault.'),
  ('at-1063-hi-tora-fire-tiger', 4, 'Laser Fingers (2)', '3D6 M.D. per single blast; simultaneous blasts not possible', 1, '2000 ft (610 m)', 'Equal to the combined hand to hand attacks of the pilot or co-pilot (usually 4-6)', 'Effectively unlimited', NULL, 'First finger of each hand. Primary defense, secondary assault.'),
  ('at-1063-hi-tora-fire-tiger', 5, 'Chest Spray', 'Chemical Stench: no damage, -4 initiative, -2 strike/parry/dodge, -20% skills (half on successful save vs non-lethal poison), smell lasts 1D4 days and carries 2500 ft (762 m); M.D. Acid: 3D6 M.D. per melee for 1D6+1 rounds (1D6 M.D. vs elementals, ancient dragons, gods), triple if sprayed in eyes, mouth or open wounds; Tear Gas: -10 strike/parry/dodge, -3 initiative, lose one attack per melee for 1D6+1 rounds, lasts 3D4 minutes; Fire Retardant Foam: no damage; Water/Holy Water: 1D6x10 to vampires single spray, 3D6x10 triple spray', 1, '120 ft (36.6 m), 25% to 50% shorter against a strong wind', 'Equal to the combined hand to hand attacks of the pilot or co-pilot (usually 4-6)', '72 single sprays (24 triple sprays); 12 per spray housing, 3 housings per breastplate; typically one or two chemicals, one type per breastplate', NULL, 'Area: single spray 10 ft (3 m) diameter, double 20 ft (6.0 m), triple 30 ft (9.1 m). Tear gas cloud 25 ft (7.6 m) dissipates in about 5 minutes. Only acid and holy water do damage; is_mega_damage set 0 because the mix is chemical effects, not one mega-damage number.'),
  ('at-1063-hi-tora-fire-tiger', 6, 'Hand to Hand Combat', 'Restrained Punch 1D4 M.D.; Full Strength Punch or Kick 2D6 M.D.; Power Punch 3D6+4 M.D. (two attacks); Vibro-Claw Punch/Stab/Slash 4D6 M.D.; Vibro-Claw Power Punch/Stab 1D4x10+8 M.D. (two attacks); Crush, Pry or Tear 1D6 M.D.; Leap Kick 4D6 M.D. (two attacks); Body Flip/Throw 1D4 M.D.; Body Block/Ram 2D4 M.D.; Stomp 1D4 M.D. against man-sized targets', 1, 'Hand to hand', NULL, NULL, '+4 to parry, +3 to dodge, +2 to strike in hand to hand. All abilities as the UAR-1 Enforcer (Rifts RPG p.44-45) except as listed', 'Four giant vibro-blades project from the knuckles of each hand.'),
  ('ir-2015-kani-crab-walker', 1, 'Short-Range Torpedo/Missile Launcher (1)', 'Varies with torpedo type; standard mix of high explosive 2D4x10 M.D. and plasma 1D6x10 M.D. torpedoes or missiles', 1, '5 miles (8 km)', 'One at a time, or volleys of two, three or four', '8', NULL, 'Mounted on the back; primary anti-submarine, secondary defense. Torpedoes or air missiles can be used.'),
  ('ir-2015-kani-crab-walker', 2, 'Forward Mini-Torpedo/Missile Launch Tubes (2)', 'Varies with torpedo type; standard high explosive or plasma 1D6x10 M.D.', 1, 'One mile (1.6 km)', 'One at a time, or volleys of two', 'Six; three in each launch tube', NULL, 'Primary anti-armor, secondary anti-monster. Fires any mini-torpedo or mini-missile.'),
  ('ir-2015-kani-crab-walker', 3, 'Belly Laser Turret (1)', '2D6 M.D. per single blast or 4D6 M.D. per double blast', 1, '1800 ft (549 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Double-barreled blue-green laser on the underbelly; rotates 360 degrees with a 30 degree arc of fire. Primary defense, secondary assault.'),
  ('ir-2015-kani-crab-walker', 4, 'Forearm Laser Torch (1)', 'Four settings: 2D6 S.D.C., 2D4x10 S.D.C., 1D6 M.D. and 2D6 M.D. per blast', 1, '40 ft (12.2 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Short-range repair and salvage tool; primary tool, secondary defense. is_mega_damage 1 although two of the four settings are S.D.C.'),
  ('ir-2015-kani-crab-walker', 5, 'Plasma Torch/Cutter (1)', 'Three settings: 1D4 M.D., 2D4 M.D. and 3D6 M.D. per blast', 1, '10 ft (3.0 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Cutting and welding tool above and below the waves; primary tool, secondary defense.'),
  ('ir-2015-kani-crab-walker', 6, 'Hand to Hand Combat', 'Restrained Claw Strike 1D4 M.D.; Full Strength Claw Strike 1D6 M.D.; Power Claw Strike 2D6 M.D. (two attacks); Crush, Pry or Tear 1D4x10 M.D.; Body Block/Tackle 6D6 M.D.; Propulsion Assisted Body Block 4D6 M.D.; no kicks; no body flip/throw', 1, 'Hand to hand', 'Two attacks per melee to start; +1 attack at levels six and twelve', NULL, '+2 to dodge (+4 underwater), +2 to roll with impact/fall', 'Crab-Walker Combat Training; see Basic Robot Combat Training, Rifts RPG p.44-45.'),
  ('ir-2020-wrecker', 1, 'Forearm Buzz-Saws (2)', '5D6 M.D. each', 1, NULL, NULL, NULL, NULL, 'A large circular saw designed for cutting M.D.C. materials. No range, rate of fire or payload is printed.'),
  ('ir-2020-wrecker', 2, 'Plasma Cutter (1; hand)', 'Four settings: 1D6x10 S.D.C., 3D6x10 S.D.C., 3D6 M.D. and 1D4x10 M.D. per blast', 1, '20 ft (6.1 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'First finger of the right or left hand, per pilot requirements. Primary cutting and welding, secondary mining and demolition. is_mega_damage 1 although two settings are S.D.C.'),
  ('ir-2020-wrecker', 3, 'Laser Torch in the Small Arm (1)', 'Four settings: 3D6 S.D.C., 1D6x10 S.D.C., 1D6 M.D. and 2D6 M.D. per blast', 1, '200 ft (61.0 m)', 'Equal to the combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Built into the forearm of one small grasping arm, usually the right; the left has a computer jack. Primary cutting and welding tool, secondary defense. The small arms can wield pistols, rifles, swords, clubs and tools. is_mega_damage 1 although two settings are S.D.C.'),
  ('ir-2020-wrecker', 4, 'Fusion Block Compartment (1)', 'Varies with type, 1D4x10 to 4D6x10 M.D. (see CS Explosives, Rifts RPG p.204)', 1, 'Blast radius confined to a 10 ft (3.0 m) diameter. Throwing range by a human 1D6x10 ft (3.0 to 36.5 m) maximum, +20 ft (6.1 m) if thrown by the small robot arms; the robot can lob a block up to 250 ft (76.2 m) with the large arms', 'Setting and placing the bomb takes one full melee round (15 seconds); setting and throwing the block counts as two melee actions', '10 fusion blocks maximum; alternatively 26 hand grenades or blasting caps, or three satchel charges', 'A thrown block is -4 to strike the target area (needs a 16 or better to hit an exact location)', 'Hip compartment holds five to ten fusion blocks, armed from the co-pilot console or by hand with a 30 second to 10 minute delay; designed for placement, not throwing. Primary demolition and mining. Thrown-block landing table (d100): 01-20 explodes exactly as intended; 21-40 explodes on impact; 41-60 timer scrambled, takes twice as long; 61-80 timer scrambled, takes half as long; 81-00 timer stopped, no explosion, block can be retrieved and reset. Damage: see CS Explosives, Rifts RPG p.204.'),
  ('ir-2020-wrecker', 5, 'Optional Laser Turrets (1 or 2)', NULL, 0, NULL, NULL, NULL, NULL, 'Optional system for use by mercenaries and adventurers. Turrets rotate 90 degrees side to side with a 45 degree arc of fire. The book prints no damage, range, rate of fire or payload for it.'),
  ('ir-2020-wrecker', 6, 'Optional Shoulder Mini-Missile Launchers (2) and/or Back Launcher (1)', 'Varies with missile type; standard armor piercing 1D4x10 M.D., plasma or Heavy-Hitters 1D6x10 M.D.', 1, 'Usually about a mile (1.6 km)', 'One at a time, or volleys of two, three or four', '24 mini-missiles per launcher, or 8 for short-range missiles', NULL, 'Standard mini-missile or short-range missile launchers. Primary defense, secondary anti-armor/assault. Any mini-missile type can be used.'),
  ('ir-2020-wrecker', 7, 'Hand to Hand Combat', 'Restrained Punch 1D6 M.D.; Full Strength Punch 3D6 M.D.; Power Punch 1D6x10 M.D. (counts as two attacks); Pry, Crush or Tear 2D4 M.D.; Kick 3D6 M.D.; Leap Kick 5D6 M.D. (counts as two melee attacks); Body Flip/Throw 2D4 M.D.; Body Block/Tackle 3D6 M.D.; Stomp 2D4 M.D. against man-sized targets', 1, 'Hand to hand', 'Starts with one attack per melee round plus those of the pilot; +1 additional attack at levels 4, 8 and 12, only for operators skilled in piloting robots', NULL, NULL, 'Not designed for combat since it tends to be slow; capacities are available to pilots with basic robot combat or piloting skills.'),
  ('ir-2040-destroyer', 1, 'Shoulder Mini-Missile Launchers (2)', 'By missile type; standard armor piercing 1D4x10 M.D., plasma or Heavy-Hitter 1D6x10 M.D.', 1, 'About a mile (1.6 km)', 'One at a time, or volleys of two, three or four', '16 total; 8 in each launcher', NULL, 'Primary Assault; secondary Anti-Armor.'),
  ('ir-2040-destroyer', 2, 'IR-60 Rail Gun', 'Full burst (40 rounds) 1D4x10 M.D.; 10-shot burst 2D6 M.D.', 1, '4000 ft (1220 m)', 'Equal to combined hand to hand attacks (usually 4-6)', 'Large drum 2400 rounds (60 full bursts or 240 short); small hip drum 1200 rounds (30 full or 120 short); clip magazine 200 rounds (5 full bursts), usually silver ammo', NULL, 'Same gun as the Katana power armor. Gun 90 lbs (40.8 kg), ammo drum 120 lbs (54 kg). Large back drum prevents use of the jet pack. Reload 5 minutes untrained, 1 minute trained in power armor; P.S. 26+ needed. Primary Assault.');

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note)
VALUES
  ('ir-2040-destroyer', 3, 'Forearm Lasers (2)', '2D6 M.D. or 4D6 M.D. per single blast; 4D6 M.D. or 8D6 M.D. per simultaneous double blast', 1, '2000 ft (610 m)', 'Equal to combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Primary Assault; secondary Defense. Each large arm has one.'),
  ('ir-2040-destroyer', 4, 'Laser Torch in the Small Arm (1)', 'Four settings: 3D6 S.D.C., 1D6x10 S.D.C., 1D6 M.D., 2D6 M.D. per blast', 1, '200 ft (61.0 m)', 'Equal to combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Primary cutting and welding tool; secondary Defense. Usually the right small arm; the left has a computer jack. Small arms can also wield pistols, rifles, swords, clubs and tools. is_mega_damage=1 although two settings are S.D.C.'),
  ('ir-2040-destroyer', 5, 'Grenade Storage Compartment (1)', 'Varies by type, typically 2D6 to 5D6 M.D., or smoke, stun and tear gas', 1, '120 ft (36.5 m) thrown by humans or small arms; large arms lob 300 ft (91.5 m); -1 to strike', 'Each throw counts as one melee action/attack', '10 hand grenades, or one satchel charge and two grenades', NULL, 'Primary Assault. Hip compartment.'),
  ('ir-2040-destroyer', 6, 'Optional Rifle and Sidearms', NULL, 0, NULL, NULL, NULL, NULL, 'Small arms can use energy rifles, pistols, vibro-blades or other conventional weapons.'),
  ('ir-2040-destroyer', 7, 'Hand to Hand Combat', 'Restrained punch 1D4 M.D.; full strength punch 2D6 M.D.; power punch (two attacks) 1D4x10 M.D.; kick 2D6 M.D.; leap kick (two attacks) 4D6 M.D.; body flip/throw 1D6 M.D.; body block/tackle 2D4 M.D.; stomp 1D4 M.D. vs man-sized targets', 1, 'Hand to hand', NULL, NULL, '2 attacks per melee plus the pilot; +1 attack at levels 5, 10, 15; +1 initiative; +1 strike; +2 parry; +3 dodge; +3 roll with impact or fall', 'Applies to elite robot pilots; basic piloting as in the Rifts RPG. Printed 170. The hand to hand block on printed 168 is the IR-2020 Wrecker, not this robot.'),
  ('ir-2050-apocalypse', 1, 'Medium-Range Missile Launchers (2)', 'By missile type; standard Heavy-Hitters 3D4x10 M.D., high explosive or plasma 2D6x10 M.D. each; fragmentation 2D4x10 M.D.', 1, 'Varies with missile type', 'One at a time, or volleys of two, four and eight', '8; four in each launcher', NULL, 'Mounted above each shoulder, usually fired by the co-pilot. Primary Assault; secondary Anti-Armor/Anti-Aircraft.'),
  ('ir-2050-apocalypse', 2, 'Chest Mini-Missile Launchers (4)', 'By missile type; standard armor piercing 1D4x10 M.D., plasma or Heavy-Hitters 1D6x10 M.D.', 1, 'About a mile (1.6 km)', 'One at a time, or volleys of two or four', '40; 10 in each launcher', NULL, 'Hidden under chest armor with a hatch that snaps open; pilot and/or co-pilot. Primary Assault; secondary Anti-Armor.'),
  ('ir-2050-apocalypse', 3, 'Forearm Lasers (2)', '1D4x10 M.D. per single blast; 2D4x10 M.D. per simultaneous blast from both arms', 1, '2000 ft (610 m)', 'Equal to that of the pilot', 'Effectively unlimited', NULL, 'Double-barrel; pilot controls. Primary Assault; secondary Anti-Aircraft and Anti-Missile.'),
  ('ir-2050-apocalypse', 4, 'Belly Rail Gun (1)', 'Burst of 60 rounds: 2D4x10 M.D.', 1, '6000 ft (1830 m)', 'Bursts or wild fire only', 'Internal 12,000-round drum, 200 bursts', NULL, 'Rotates 90 degrees in any direction; silver ammo possible. Reload needs specialised equipment, trained technicians and several minutes. Primary Anti-Personnel; secondary Assault.'),
  ('ir-2050-apocalypse', 5, 'Plasma Belly Gun', '1D6x10 M.D. per blast', 1, '1600 ft (487.6 m)', 'Equal to the gunner combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Swivels 90 degrees; co-pilot or a gunner. Primary Assault; secondary Anti-Supernatural Beings. The location table calls it Belly Plasma Ejector.'),
  ('ir-2050-apocalypse', 6, 'Leg Mini-Missile Launchers (4)', 'By missile type; standard fragmentation 5D6 M.D.', 1, 'About one mile (1.6 km)', 'One at a time, or volleys of two or five', '40; 10 per launcher', NULL, 'Two on each hip; fired by the gunners. Primary Anti-Personnel; secondary Assault.'),
  ('ir-2050-apocalypse', 7, 'Main Weapon Arms (2): Short-Range Missile Launchers (1 per arm)', 'By missile type; plasma 2D6x10 M.D. and armor piercing 1D6x10 M.D. most often used', 1, 'Typically four miles (6.4 km)', 'One at a time, or volleys of two or four', '16; eight in each arm', NULL, 'Each arm is operated by a gunner. Primary Anti-Personnel/Assault; secondary Anti-Armor.'),
  ('ir-2050-apocalypse', 7, 'Main Weapon Arms (2): High-Powered Laser Cannon (1 per arm)', '1D4x10 M.D. per single blast; 2D4x10 M.D. per simultaneous blasts from both arms', 1, '6000 ft (1830 m)', 'Equal to that of the gunner', 'Effectively unlimited', NULL, 'Primary Assault; secondary Anti-Aircraft and Anti-Missile.'),
  ('ir-2050-apocalypse', 7, 'Main Weapon Arms (2): Four Pronged Blades', 'Slash 4D6 M.D.; stab 6D6 M.D.; power stab 1D6x10 M.D. (counts as two attacks)', 1, 'Hand to hand', NULL, NULL, NULL, 'Four large M.D. blades protrude past the gun barrel and launch tube.'),
  ('ir-2050-apocalypse', 8, 'Hand to Hand Combat', 'Restrained punch 2D6 M.D.; full strength punch 4D6 M.D.; power punch (two attacks) 8D6 M.D.; blade slash 4D6 M.D.; blade stab 6D6 M.D.; blade power stab 1D6x10 M.D. (two attacks); crush, pry or tear 2D6 M.D.; kick 4D6 M.D. (leap kick not possible); body flip/throw 2D6 M.D.; body block/tackle 5D6 M.D.; stomp 2D4 M.D. vs man-sized targets', 1, 'Hand to hand', NULL, NULL, NULL, 'Special training in piloting the IR-2050; basic robot combat is Rifts RPG p.44. No bonus list is printed.'),
  ('ir-2050-apocalypse-drone', 1, 'Weapon Arms', '1D4x10+8 M.D. per single blast; 4D6x10 per double blast at the same target', 1, '300 ft (91.4 m)', 'Equal to the remote operator hand to hand attacks, +2 attacks per melee', '200 blasts; 100 per arm before recharging (recharge by reattaching to the IR-2050)', '-1 to strike when firing at two different targets; drone bonus +2 dodge plus the remote operator bonuses', 'Pair of small arms under the drone, each rotating 360 degrees with a 100 degree arc of fire. Primary Assault and Anti-aircraft; secondary Reconnaissance. Ordinal 10 is mine: the book numbers these as the drone own 1-2.'),
  ('ir-2050-apocalypse-drone', 2, 'Mini-Missiles', '1D4x10 M.D. each', 1, 'One mile (1.6 km)', 'One or two at a time', '4 mini-missiles', NULL, 'Two under each wing. Ordinal 11 is mine: the book numbers this as the drone own 2.'),
  ('ir-2060-banshee', 1, 'Sonic Cannon', '1D6x10 M.D. per blast, plus 3D6 M.D. to a 10 ft diameter around the blast; double damage and range underwater', 1, '2000 ft (610 m)', 'Equal to combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Above the right shoulder (intro says right or left shoulder, locked up or forward); runs off the nuclear supply; only the target is affected by the blast. Primary Assault; secondary Anti-Personnel.'),
  ('ir-2060-banshee', 2, 'Wing Mini-Missile Launchers (2)', 'By missile type; standard mix of fragmentation 5D6 M.D. and plasma 1D6x10 M.D.', 1, 'About one mile (1.6 km)', 'One at a time, or volleys of two, four or five', '20; 10 in each launcher', NULL, 'Primary Anti-Aircraft and Anti-Missile; secondary Assault. Standard complement printed as 10 fragmentation and 10 plasma.'),
  ('ir-2060-banshee', 3, 'Light Wrist Laser (2)', '3D6 M.D. per blast', 1, '2000 ft (610 m)', 'Equal to combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Blue-green laser in each wrist; pilot raises the hand, points and shoots. Primary Defense; secondary Assault. Damage is at the foot of printed 174; range, rate and payload at the top of 176.'),
  ('ir-2060-banshee', 4, 'Forearm Vibro-Swords (2)', '5D6 M.D.', 1, 'Hand to hand', NULL, NULL, NULL, 'Five foot (1.5 m) retractable vibro-swords housed in the forearms.'),
  ('ir-2060-banshee', 5, 'Hand to Hand Combat', 'Restrained claw strike 1D6 M.D.; full strength claw strike 3D6 M.D.; power claw strike (two attacks) 1D4x10 M.D.; crush, pry or tear 3D6 M.D.; kick 3D6 M.D.; leap kick (two attacks) 1D4x10 M.D.; body flip/throw 1D6 M.D.; body block/tackle 3D6 M.D.; stomp 1D6 M.D. vs man-sized targets', 1, 'Hand to hand', NULL, NULL, '+1 initiative; +1 strike; +1 parry; +2 dodge (+4 when flying); +3 pull punch; +2 roll with fall or impact; 2 attacks per melee plus the pilot; +1 attack at levels 5 and 10', 'Heading: Damage & Bonuses from Banshee Combat Training. Basic robot combat Rifts RPG p.44.'),
  ('ir-2070-gemini', 1, 'Shoulder Mini-Missile Launchers (2)', 'By missile type; standard armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D., heat-seeking', 1, 'About one mile (1.6 km)', 'One at a time, or volleys of two, three or four', '24; twelve in each launcher', NULL, 'Primary Anti-Aircraft; secondary Assault. Printed on 178.'),
  ('ir-2070-gemini', 2, 'Forearm Laser', '5D6 M.D. per blast; half when cloaked', 1, '3000 ft (910 m); half when cloaked', 'Equal to combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Right arm. Primary Assault/Anti-Armor; secondary Anti-Aircraft.'),
  ('ir-2070-gemini', 3, 'Forearm Vibro-Sword (1)', '5D6 M.D.', 1, 'Hand to hand', NULL, NULL, NULL, 'Retractable five foot (1.5 m) vibro-sword in the left forearm.'),
  ('ir-2070-gemini', 4, 'Optional IR-120 Rail Gun', 'Full burst (60 rounds) 1D6x10 M.D.; 10-shot burst 2D6 M.D.', 1, '7000 ft (2133 m)', 'Equal to combined hand to hand attacks (usually 4-6)', '24,000 rounds per large drum: 400 full bursts or 2400 short bursts', NULL, 'Giant version of the IR-60 (Katana). Gun 290 lbs (130 kg); ammo drum and generator 600 lbs (270 kg) on the back. Own portable generator; silver ammo possible. Cloaking glitch: each shot makes the cloak blink off for two seconds. Reload 5 minutes untrained, 1 minute trained; P.S. 26+. Primary Assault.'),
  ('ir-2070-gemini', 5, 'Hand to Hand Combat', 'Restrained punch 1D4 M.D.; full strength punch 2D6 M.D.; power punch (two attacks) 4D6 M.D.; crush, pry or tear 1D6 M.D.; kick 2D6 M.D.; leap kick (two attacks) 4D6 M.D.; body flip/throw 1D6 M.D.; body block/tackle 2D6 M.D.', 1, 'Hand to hand', NULL, NULL, '+2 initiative when invisible; +1 strike; +3 parry; +1 dodge, 44 when invisible (as printed); +2 roll with impact or fall; 2 attacks per melee plus the pilot; +1 attack at levels 5 and 10', 'Heading: Damage & Bonuses from Gemini Combat Training. No stomp line is printed.'),
  ('ir-4000-tatsu-dragon', 1, 'Mouth Plasma Thrower (1)', '3D6 M.D. per single blast of napalm-like fire; 01-90% chance of igniting combustibles, which then take 1D4 M.D. per melee round for at least 2D4 minutes', 1, '200 ft (61.0 m)', 'Equal to combined hand to hand attacks (usually 4-6)', '50 blasts', NULL, 'Part of item 1, Plasma Mouth Weapons. Primary Anti-Monster; secondary Anti-Personnel.'),
  ('ir-4000-tatsu-dragon', 1, 'Plasma Cannon (1)', '1D4x10 M.D. per blast', 1, '1600 ft (487 m)', 'Equal to the operator combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Part of item 1, inside the mouth; long flexible neck points it in all directions; pilot or co-pilot. Primary Defense; secondary Assault.'),
  ('ir-4000-tatsu-dragon', 2, 'Snout Mini-Missile Launchers (2)', 'By missile type; standard armor piercing 1D4x10 M.D., plasma or Heavy-Hitters 1D6x10 M.D.', 1, 'About a mile (1.6 km)', 'One at a time, or volleys of two, three or four', '24; 12 in each launcher', NULL, 'One in each nostril; pilot, co-pilot or gunner. Primary Defense; secondary Anti-Armor/Assault.');

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note)
VALUES
  ('ir-4000-tatsu-dragon', 3, 'Biting Head & Horns', 'Bite 4D6 M.D.; power bite 1D6x10 M.D. (two melee attacks); impaling horns 6D6 M.D.; head butt without horns 2D6 M.D.', 1, 'Hand to hand', NULL, NULL, '+2 parry with the horns', 'Three horns (top and two sides), each rotates 180 degrees.'),
  ('ir-4000-tatsu-dragon', 4, 'Palm Lasers (2)', '2D6 M.D. per single blast; 4D6 M.D. per simultaneous blasts', 1, '2000 ft (610 m)', 'Equal to the pilot or co-pilot combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'In the palm of each hand. Primary Defense; secondary Assault.'),
  ('ir-4000-tatsu-dragon', 5, 'Shoulder Missile Launcher', 'By missile type; standard load smart bombs (+5 strike) with plasma 4D6x10 M.D. or multiple warheads 5D6x10 M.D.', 1, 'Varies with missile type', 'One at a time, or volleys of two or three', '12 total', '+5 to strike (heat seeker bonus)', 'Medium or long-range missiles; gunners only. Primary Anti-Aircraft.'),
  ('ir-4000-tatsu-dragon', 6, 'Tail Laser', '3D6 M.D. per single blast; 6D6 M.D. per simultaneous blasts', 1, '2000 ft (610 m)', 'Equal to the pilot or co-pilot combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Double-barreled, halfway down the tail; text says controlled exclusively by the gunners. Primary Defense; secondary Assault.'),
  ('ir-4000-tatsu-dragon', 7, 'Prehensile Tail', '3D6 M.D. per strike', 1, 'Hand to hand', NULL, NULL, NULL, 'Whip or entangle; tail P.S. 50.'),
  ('ir-4000-tatsu-dragon', 8, 'Hand to Hand Combat', 'Restrained punch 1D6 M.D.; full strength punch/claw 3D6 M.D.; power punch (two attacks) 1D4x10 M.D.; crush, pry or tear 2D6 M.D.; bite 4D6 M.D.; power bite (two attacks) 1D6x10; impaling horns 6D6 M.D.; head butt without horns 2D6 M.D.; body flip/throw 2D4 M.D.; body block/ram/tackle 4D6 M.D.; kicks not possible', 1, 'Hand to hand', NULL, NULL, '+1 strike with tiny hands; +2 strike with head/bite; +2 strike with tail and weapons; +2 parry with horns; +4 parry with tail; +3 dodge for the head; +1 dodge with entire body; +2 roll with impact or fall; 3 attacks per melee plus the pilot; +1 attack at levels 5, 10 and 15', 'Heading: Damage & Bonuses from Tatsu Combat Training. The list continues from printed 180 onto 181 (cache p182), outside the slice but read.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 21 Japan vehicles are in' AS assertion, count(*) AS got, 21 AS want
  FROM vehicles WHERE slug IN ('at-samurai-samas-pa-10a', 'usa-g10a1-point-glitter-boy', 'usa-g10a2-hawkeye-glitter-boy', 'atpa-85-power-spy', 'h-brand-ninjabot', 'ipa-40-dai-katana-bugei', 'ipa-45-ikusa', 'ipa-50-grenadier', 'ipa-60-tazu-tengu', 'ipa-62-super-tengu', 'ipa-70-mizu-mi', 'at-1053-ka-kuma-metal-bear', 'at-1063-hi-tora-fire-tiger', 'ir-2015-kani-crab-walker', 'ir-2020-wrecker', 'ir-2040-destroyer', 'ir-2050-apocalypse', 'ir-2050-apocalypse-drone', 'ir-2060-banshee', 'ir-2070-gemini', 'ir-4000-tatsu-dragon') AND source_book LIKE 'Rifts World Book 8: Japan p.%';
SELECT 'their 221 M.D.C. locations are in' AS assertion, count(*) AS got, 221 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('at-samurai-samas-pa-10a', 'usa-g10a1-point-glitter-boy', 'usa-g10a2-hawkeye-glitter-boy', 'atpa-85-power-spy', 'h-brand-ninjabot', 'ipa-40-dai-katana-bugei', 'ipa-45-ikusa', 'ipa-50-grenadier', 'ipa-60-tazu-tengu', 'ipa-62-super-tengu', 'ipa-70-mizu-mi', 'at-1053-ka-kuma-metal-bear', 'at-1063-hi-tora-fire-tiger', 'ir-2015-kani-crab-walker', 'ir-2020-wrecker', 'ir-2040-destroyer', 'ir-2050-apocalypse', 'ir-2050-apocalypse-drone', 'ir-2060-banshee', 'ir-2070-gemini', 'ir-4000-tatsu-dragon');
SELECT 'their 126 weapon entries are in' AS assertion, count(*) AS got, 126 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('at-samurai-samas-pa-10a', 'usa-g10a1-point-glitter-boy', 'usa-g10a2-hawkeye-glitter-boy', 'atpa-85-power-spy', 'h-brand-ninjabot', 'ipa-40-dai-katana-bugei', 'ipa-45-ikusa', 'ipa-50-grenadier', 'ipa-60-tazu-tengu', 'ipa-62-super-tengu', 'ipa-70-mizu-mi', 'at-1053-ka-kuma-metal-bear', 'at-1063-hi-tora-fire-tiger', 'ir-2015-kani-crab-walker', 'ir-2020-wrecker', 'ir-2040-destroyer', 'ir-2050-apocalypse', 'ir-2050-apocalypse-drone', 'ir-2060-banshee', 'ir-2070-gemini', 'ir-4000-tatsu-dragon');

